namespace CourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace CourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace CourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Student name is required.")]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^STU-\d{4}$", ErrorMessage = "Student ID must be in the format STU-XXXX (e.g., STU-1234).")]
    public string StudentId { get; set; } = string.Empty;

    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public interface ICatalogService
{
    List<Department> GetDepartments();
    List<Course> GetCourses(string? search, string? departmentCode);
    Course? GetCourse(int id);
    List<Course> GetFeaturedCourses();
    void SubmitEnrollment(EnrollmentRequest request);
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class InMemoryCatalogService : ICatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public InMemoryCatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Explore the foundations and frontiers of computing, from programming fundamentals to artificial intelligence." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Develop rigorous analytical skills through the study of calculus, algebra, and applied mathematics." },
            new() { Id = 3, Name = "English", Code = "ENG", Description = "Strengthen your writing, critical reading, and literary analysis skills across genres and periods." },
            new() { Id = 4, Name = "Physics", Code = "PHYS", Description = "Investigate the fundamental laws governing matter, energy, and the universe." }
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, DepartmentId = 1, Code = "CS101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures. No prior experience required.", Credits = 3, Schedule = "MWF 9:00-9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has over 15 years of experience teaching introductory computer science. She holds a Ph.D. from MIT and has published extensively on CS education.", IsFeatured = true },
            new() { Id = 2, DepartmentId = 1, Code = "CS201", Title = "Data Structures", Description = "Study essential data structures including arrays, linked lists, trees, graphs, and hash tables. Analyze algorithmic complexity and learn to choose appropriate structures for different problems.", Credits = 4, Schedule = "TTh 10:30-11:50 AM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park specializes in algorithm design and software engineering. He previously worked at Google on large-scale distributed systems." },
            new() { Id = 3, DepartmentId = 1, Code = "CS301", Title = "Algorithms", Description = "Dive deep into algorithm design techniques including divide-and-conquer, dynamic programming, and greedy algorithms. Covers NP-completeness and computational complexity theory.", Credits = 4, Schedule = "MWF 1:00-1:50 PM", InstructorName = "Dr. Maria Rodriguez", InstructorBio = "Dr. Rodriguez is a leading researcher in theoretical computer science with publications in top-tier venues." },
            new() { Id = 4, DepartmentId = 1, Code = "CS401", Title = "Machine Learning", Description = "Explore supervised and unsupervised learning, neural networks, and deep learning. Hands-on projects using real-world datasets prepare students for careers in AI and data science.", Credits = 4, Schedule = "TTh 2:00-3:20 PM", InstructorName = "Dr. Alan Wu", InstructorBio = "Dr. Wu leads the university's AI research lab and has published over 50 papers on machine learning and computer vision.", IsFeatured = true },

            // Mathematics
            new() { Id = 5, DepartmentId = 2, Code = "MATH101", Title = "Calculus I", Description = "An introduction to differential and integral calculus. Topics include limits, derivatives, integrals, and the Fundamental Theorem of Calculus. Applications to physics and engineering are emphasized.", Credits = 4, Schedule = "MWF 10:00-10:50 AM", InstructorName = "Dr. Robert Taylor", InstructorBio = "Dr. Taylor has been teaching calculus for 20 years and is a recipient of the university's Distinguished Teaching Award." },
            new() { Id = 6, DepartmentId = 2, Code = "MATH201", Title = "Linear Algebra", Description = "Study vector spaces, linear transformations, matrices, determinants, and eigenvalues. This course provides the mathematical foundation for many areas of science and engineering.", Credits = 3, Schedule = "TTh 9:00-10:20 AM", InstructorName = "Dr. Emily Zhang", InstructorBio = "Dr. Zhang's research focuses on applied linear algebra and numerical methods. She consults for several aerospace companies.", IsFeatured = true },
            new() { Id = 7, DepartmentId = 2, Code = "MATH301", Title = "Differential Equations", Description = "Covers ordinary differential equations, Laplace transforms, and systems of equations. Applications to modeling physical, biological, and economic systems are explored throughout the course.", Credits = 3, Schedule = "MWF 11:00-11:50 AM", InstructorName = "Dr. Robert Taylor", InstructorBio = "Dr. Taylor has been teaching calculus for 20 years and is a recipient of the university's Distinguished Teaching Award." },

            // English
            new() { Id = 8, DepartmentId = 3, Code = "ENG101", Title = "Composition I", Description = "Develop essential academic writing skills including thesis development, argumentation, and research methods. Students write multiple essays and learn to revise effectively.", Credits = 3, Schedule = "MWF 9:00-9:50 AM", InstructorName = "Prof. Linda Morrison", InstructorBio = "Prof. Morrison is a published author and writing instructor with expertise in rhetoric and composition studies." },
            new() { Id = 9, DepartmentId = 3, Code = "ENG201", Title = "American Literature", Description = "Survey major works and movements in American literature from the colonial period to the present. Authors studied include Hawthorne, Twain, Fitzgerald, Morrison, and contemporary voices.", Credits = 3, Schedule = "TTh 1:00-2:20 PM", InstructorName = "Dr. Michael Brooks", InstructorBio = "Dr. Brooks is a scholar of 20th-century American fiction and has authored two books on the American literary canon." },
            new() { Id = 10, DepartmentId = 3, Code = "ENG301", Title = "Creative Writing", Description = "Workshop-based course in fiction and poetry writing. Students produce original works, participate in peer workshops, and study craft elements through published examples.", Credits = 3, Schedule = "TTh 3:00-4:20 PM", InstructorName = "Prof. Karen White", InstructorBio = "Prof. White is an award-winning poet and fiction writer. Her work has appeared in The New Yorker and The Atlantic.", IsFeatured = true },

            // Physics
            new() { Id = 11, DepartmentId = 4, Code = "PHYS101", Title = "Physics I", Description = "Introduction to classical mechanics covering kinematics, Newton's laws, energy, momentum, and rotational motion. Includes a weekly laboratory component with hands-on experiments.", Credits = 4, Schedule = "MWF 10:00-10:50 AM", InstructorName = "Dr. David Kim", InstructorBio = "Dr. Kim is an experimental physicist whose research focuses on condensed matter physics and materials science." },
            new() { Id = 12, DepartmentId = 4, Code = "PHYS201", Title = "Electromagnetism", Description = "Study electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics. The course builds on calculus and introduces vector analysis as needed.", Credits = 4, Schedule = "TTh 10:30-11:50 AM", InstructorName = "Dr. Susan Li", InstructorBio = "Dr. Li's research in electromagnetic theory has been funded by the National Science Foundation for over a decade." },
            new() { Id = 13, DepartmentId = 4, Code = "PHYS301", Title = "Quantum Mechanics", Description = "Introduction to quantum theory including wave-particle duality, the Schrödinger equation, and quantum states. Explores applications to atomic structure and modern physics.", Credits = 3, Schedule = "MWF 2:00-2:50 PM", InstructorName = "Dr. David Kim", InstructorBio = "Dr. Kim is an experimental physicist whose research focuses on condensed matter physics and materials science." }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public List<Course> GetCourses(string? search, string? departmentCode)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentCode))
        {
            var dept = _departments.FirstOrDefault(d => d.Code.Equals(departmentCode, StringComparison.OrdinalIgnoreCase));
            if (dept != null)
                query = query.Where(c => c.DepartmentId == dept.Id);
        }

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public void SubmitEnrollment(EnrollmentRequest request)
    {
        // In-memory implementation — no persistence needed
    }
}

