@page "/courses"
@using CourseCatalog.Components.Shared
@inject ICatalogService CatalogService

<PageTitle>Courses - University Course Catalog</PageTitle>

<h1>Course Catalog</h1>

<form method="get" action="/courses" class="course-search-form mb-4">
    <div class="row g-2 align-items-end">
        <div class="col-md-5">
            <label for="search" class="form-label">Search</label>
            <input type="text" id="search" name="search" value="@Search" class="form-control" placeholder="Search by title, code, or keyword..." />
        </div>
        <div class="col-md-4">
            <label for="department" class="form-label">Department</label>
            <select id="department" name="department" class="form-select">
                <option value="">All Departments</option>
                @foreach (var dept in departments)
                {
                    <option value="@dept.Code" selected="@(Department == dept.Code)">@dept.Name</option>
                }
            </select>
        </div>
        <div class="col-md-3">
            <button type="submit" class="btn btn-primary w-100">Search</button>
        </div>
    </div>
</form>

<div class="department-filter-links mb-3">
    <a href="/courses" class="btn btn-sm @(string.IsNullOrEmpty(Department) ? "btn-primary" : "btn-outline-primary")">All</a>
    @foreach (var dept in departments)
    {
        <a href="/courses?department=@dept.Code" class="btn btn-sm @(Department == dept.Code ? "btn-primary" : "btn-outline-primary")">@dept.Name</a>
    }
</div>

@if (courses.Count == 0)
{
    <p class="text-muted">No courses found matching your criteria.</p>
}
else
{
    <div class="course-list">
        @foreach (var course in courses)
        {
            <CourseListItem Course="course" />
        }
    </div>
}

@code {
    [SupplyParameterFromQuery(Name = "search")]
    private string? Search { get; set; }

    [SupplyParameterFromQuery(Name = "department")]
    private string? Department { get; set; }

    private List<Course> courses = new();
    private List<Department> departments = new();

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();
        courses = CatalogService.GetCourses(Search, Department);
    }
}

@page "/courses/{Id:int}"
@inject ICatalogService CatalogService

<PageTitle>@(course?.Title ?? "Course Not Found") - University Course Catalog</PageTitle>

@if (course is null)
{
    <h1>Course Not Found</h1>
    <p>The requested course could not be found.</p>
    <a href="/courses" class="btn btn-primary">Back to Courses</a>
}
else
{
    <div class="course-detail">
        <nav aria-label="breadcrumb">
            <ol class="breadcrumb">
                <li class="breadcrumb-item"><a href="/courses">Courses</a></li>
                <li class="breadcrumb-item"><a href="/courses?department=@departmentCode">@departmentName</a></li>
                <li class="breadcrumb-item active" aria-current="page">@course.Code</li>
            </ol>
        </nav>

        <h1>@course.Code — @course.Title</h1>

        <div class="course-detail-meta">
            <span class="badge bg-primary">@course.Credits Credits</span>
            <span class="badge bg-secondary">@departmentName</span>
        </div>

        <section class="course-detail-section">
            <h2>Description</h2>
            <p>@course.Description</p>
        </section>

        <section class="course-detail-section">
            <h2>Schedule</h2>
            <p>@course.Schedule</p>
        </section>

        <section class="course-detail-section">
            <h2>Instructor</h2>
            <h4>@course.InstructorName</h4>
            <p>@course.InstructorBio</p>
        </section>

        <div class="course-detail-actions">
            <a href="/enroll?courseid=@course.Id" class="btn btn-success btn-lg">Enroll in This Course</a>
            <a href="/courses" class="btn btn-outline-secondary">Back to Courses</a>
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Course? course;
    private string departmentName = string.Empty;
    private string departmentCode = string.Empty;

    protected override void OnInitialized()
    {
        course = CatalogService.GetCourse(Id);
        if (course != null)
        {
            var dept = CatalogService.GetDepartments().FirstOrDefault(d => d.Id == course.DepartmentId);
            departmentName = dept?.Name ?? "Unknown";
            departmentCode = dept?.Code ?? "";
        }
    }
}

@page "/enroll"
@inject ICatalogService CatalogService

<PageTitle>Enroll - University Course Catalog</PageTitle>

<h1>Course Enrollment</h1>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>Enrollment Submitted!</h4>
        <p>Thank you, <strong>@FormModel!.StudentName</strong>. Your enrollment request for <strong>@enrolledCourseTitle</strong> has been received.</p>
        <a href="/courses" class="btn btn-primary">Browse More Courses</a>
    </div>
}
else
{
    <div class="enrollment-form">
        <EditForm Model="FormModel" method="post" FormName="enrollment" OnValidSubmit="HandleSubmit" Enhance>
            <AntiforgeryToken />
            <DataAnnotationsValidator />
            <ValidationSummary class="text-danger" />

            <div class="mb-3">
                <label for="studentName" class="form-label">Student Name</label>
                <InputText id="studentName" @bind-Value="FormModel!.StudentName" class="form-control" placeholder="Enter your full name" />
            </div>

            <div class="mb-3">
                <label for="studentId" class="form-label">Student ID</label>
                <InputText id="studentId" @bind-Value="FormModel!.StudentId" class="form-control" placeholder="STU-XXXX" />
                <div class="form-text">Format: STU- followed by 4 digits (e.g., STU-1234)</div>
            </div>

            <div class="mb-3">
                <label for="courseId" class="form-label">Course</label>
                <InputSelect id="courseId" @bind-Value="FormModel!.CourseId" class="form-select">
                    <option value="0">-- Select a Course --</option>
                    @foreach (var course in courses)
                    {
                        <option value="@course.Id">@course.Code — @course.Title (@course.Credits credits)</option>
                    }
                </InputSelect>
            </div>

            <button type="submit" class="btn btn-success">Submit Enrollment</button>
            <a href="/courses" class="btn btn-outline-secondary ms-2">Cancel</a>
